import { Accessor, createEffect, createSignal, on, onCleanup, onMount, Signal } from "solid-js";

/**
 * Track the engine ready status globally.
 */
let engineIsReady = false;

/**
 * Create a cancelleable engine event registration.
 * This internally ensures that engine.whenReady is resolved.
 * `clear` *must* be called in order to unregister the event.
 */
function registerEngineEvent<Name extends GameCoreEvent["name"]>(
	name: Name | string,
	callback: (...args: unknown[]) => void,
): EventHandle {
	if (engineIsReady) {
		engine.on(name, callback);
		return {
			clear: () => engine.off(name, callback),
		};
	} else {
		let isRegistered = false;
		let isCancelled = false;
		engine.whenReady.then(() => {
			engineIsReady = true;

			if (!isCancelled) {
				engine.on(name, callback);
			}
			isRegistered = true;
		});

		return {
			clear: () => {
				if (isRegistered) {
					engine.off(name, callback);
				} else {
					isCancelled = true;
				}
			},
		};
	}
}

interface SignalRegistration {
	signal: Signal<unknown>;
	refCount: number;
	handle: EventHandle | null;
}

const signalRegistry = new Map<string, SignalRegistration>();
/**
 * Exposes a Game Core event to SolidJS with appropriate lifecycle handling
 * Uses reference counting so events are only subscribed to a single time across multiple components
 * @param name The Game Core engine event name
 * @returns
 */
export function createEngineEvent<Name extends GameCoreEvent["name"]>(name: Name | string) {
	let registration = signalRegistry.get(name);
	if (!registration) {
		registration = {
			signal: createSignal(),
			refCount: 0,
			handle: null,
		};
	}

	onMount(() => {
		registration.refCount++;

		if (registration.refCount == 1) {
			registration.handle = registerEngineEvent(name, registration.signal[1]);
		}
	});

	onCleanup(() => {
		registration.refCount--;

		if (registration.refCount == 0) {
			registration.handle?.clear();
			registration.handle = null;
		}
	});

	return registration?.signal[0] as Accessor<Extract<GameCoreEvent, { name: Name }>["payload"]>;
}

/**
 * Gamecore does not like it when optional properties are set to undefined instead of being deleted.
 * This function deletes any undefined keys off of an object
 * @param object The object to clean
 * @returns A clean version of the object without undefined keys
 */
export function cleanObject<T>(object: T): T {
	for (const prop in object) {
		if (object[prop] === undefined) {
			delete object[prop];
		}
	}

	return object;
}

/**
 * Access the local player as a reactive signal that will be updated whenever the local player changes.
 * This is commonly used to better support HotSeat.
 */
export function useLocalPlayerId(): Accessor<PlayerId> {
	if (!UI.isInGame()) {
		return () => PlayerIds.NO_PLAYER;
	}

	const localPlayerChanged = createEngineEvent("LocalPlayerChanged");
	const [localPlayerId, setLocalPlayerId] = createSignal<PlayerId>(GameContext.localPlayerID);

	createEffect(
		on(
			localPlayerChanged,
			(data) => {
				if (data.player != localPlayerId()) {
					setLocalPlayerId(data.player);
				}
			},
			{ defer: true },
		),
	);

	return localPlayerId;
}
